        &mut self,
        view: Entity<RescopeView>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self._rescope_subscriptions = vec![
            cx.subscribe_in(&view, window, |this, _, _: &CloseRescope, window, cx| {
                this.close_rescope(window, cx)
