                    this.prompt_mode.update(cx, |prompt_mode, cx| {
                        prompt_mode.send(prompt, SendMode::Spec, Vec::new(), window, cx)
                    });
                },
            ),
            cx.observe(&view, |this, _, cx| this.refresh_jobs(cx)),
        ];
